-- 조건별 채점 결과(docs/specs/spec_grade_checks.md): checks 는 [{label, cmd}] 이고 학습자에게는 label 만 보인다.
-- 모든 조건이 통과해야 정답이며, grade_cmd 는 같은 조건을 && 로 이은 것과 같게 둔다 (verify:quests 와 조건 목록이 서로 어긋나지 않도록).
-- 조건 목록이 필요한 문제는 이 파일(과 같은 내용의 마이그레이션)에 추가한다.
UPDATE quest SET checks = '[{"label": "제목 줄이 PID RSS COMMAND 이다", "cmd": ["sh", "-c", "[ \\"$(awk ''NR==1 {print $1, $2, $3}'' /tmp/ps_cols.txt)\\" = \\"PID RSS COMMAND\\" ]"]}, {"label": "제목 아래에 프로세스가 나열되어 있다", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/ps_cols.txt)\\" -gt 1 ]"]}]', grade_cmd = '["sh", "-c", "( [ \\"$(awk ''NR==1 {print $1, $2, $3}'' /tmp/ps_cols.txt)\\" = \\"PID RSS COMMAND\\" ] ) && ( [ \\"$(wc -l < /tmp/ps_cols.txt)\\" -gt 1 ] )"]' WHERE quest_set_id = 3 AND order_index = 9;
UPDATE quest SET checks = '[{"label": "제목 줄(PID)이 있다", "cmd": ["sh", "-c", "[ \\"$(awk ''NR==1 {print $1}'' /tmp/ps_by_mem.txt)\\" = PID ]"]}, {"label": "2번째 줄이 메모리를 가장 많이 쓰는 프로세스이다", "cmd": ["sh", "-c", "[ \\"$(awk ''NR==2 {print $1}'' /tmp/ps_by_mem.txt)\\" = \\"$(pgrep -x perl | head -n 1)\\" ]"]}]', grade_cmd = '["sh", "-c", "( [ \\"$(awk ''NR==1 {print $1}'' /tmp/ps_by_mem.txt)\\" = PID ] ) && ( [ \\"$(awk ''NR==2 {print $1}'' /tmp/ps_by_mem.txt)\\" = \\"$(pgrep -x perl | head -n 1)\\" ] )"]' WHERE quest_set_id = 3 AND order_index = 10;
UPDATE quest SET checks = '[{"label": "web1 이 10.0.0.11 로 해석된다", "cmd": ["sh", "-c", "getent hosts web1 | grep -q 10.0.0.11"]}, {"label": "web2 가 10.0.0.12 로 해석된다", "cmd": ["sh", "-c", "getent hosts web2 | grep -q 10.0.0.12"]}, {"label": "db 가 10.0.0.13 으로 해석된다", "cmd": ["sh", "-c", "getent hosts db | grep -q 10.0.0.13"]}, {"label": "기존 내용(localhost)이 그대로 남아 있다", "cmd": ["sh", "-c", "getent hosts localhost >/dev/null"]}]', grade_cmd = '["sh", "-c", "( getent hosts web1 | grep -q 10.0.0.11 ) && ( getent hosts web2 | grep -q 10.0.0.12 ) && ( getent hosts db | grep -q 10.0.0.13 ) && ( getent hosts localhost >/dev/null )"]' WHERE quest_set_id = 36 AND order_index = 1;
UPDATE quest SET checks = '[{"label": "api 가 10.0.0.20 으로 해석된다", "cmd": ["sh", "-c", "getent hosts api | grep -q 10.0.0.20"]}, {"label": "api.internal 이 10.0.0.20 으로 해석된다", "cmd": ["sh", "-c", "getent hosts api.internal | grep -q 10.0.0.20"]}, {"label": "기존 내용(localhost)이 그대로 남아 있다", "cmd": ["sh", "-c", "getent hosts localhost >/dev/null"]}]', grade_cmd = '["sh", "-c", "( getent hosts api | grep -q 10.0.0.20 ) && ( getent hosts api.internal | grep -q 10.0.0.20 ) && ( getent hosts localhost >/dev/null )"]' WHERE quest_set_id = 36 AND order_index = 2;
UPDATE quest SET checks = '[{"label": "db 가 새 IP 10.0.0.31 로 해석된다", "cmd": ["sh", "-c", "getent hosts db | grep -q 10.0.0.31"]}, {"label": "옛 IP 10.0.0.30 은 더 이상 쓰이지 않는다", "cmd": ["sh", "-c", "! getent hosts db | grep -q 10.0.0.30"]}, {"label": "db 가 한 줄(IP 하나)로만 해석된다", "cmd": ["sh", "-c", "[ \\"$(getent hosts db | wc -l)\\" = 1 ]"]}, {"label": "기존 내용(localhost)이 그대로 남아 있다", "cmd": ["sh", "-c", "getent hosts localhost >/dev/null"]}]', grade_cmd = '["sh", "-c", "( getent hosts db | grep -q 10.0.0.31 ) && ( ! getent hosts db | grep -q 10.0.0.30 ) && ( [ \\"$(getent hosts db | wc -l)\\" = 1 ] ) && ( getent hosts localhost >/dev/null )"]' WHERE quest_set_id = 36 AND order_index = 3;
UPDATE quest SET checks = '[{"label": "백업 파일 /etc/hosts.bak 이 있다", "cmd": ["sh", "-c", "[ -f /etc/hosts.bak ]"]}, {"label": "수정본 /tmp/hosts.edited 에 temp 줄이 있다", "cmd": ["sh", "-c", "grep -q temp /tmp/hosts.edited"]}, {"label": "최종 /etc/hosts 에는 temp 줄이 없다", "cmd": ["sh", "-c", "! grep -q temp /etc/hosts"]}, {"label": "기존 내용(localhost)이 그대로 남아 있다", "cmd": ["sh", "-c", "getent hosts localhost >/dev/null"]}]', grade_cmd = '["sh", "-c", "( [ -f /etc/hosts.bak ] ) && ( grep -q temp /tmp/hosts.edited ) && ( ! grep -q temp /etc/hosts ) && ( getent hosts localhost >/dev/null )"]' WHERE quest_set_id = 36 AND order_index = 6;
UPDATE quest SET checks = '[{"label": "PVC data 에 StorageClass 가 지정되어 있다", "cmd": ["sh", "-c", "[ -n \\"$(kubectl get pvc data -n $NS -o jsonpath=''{.spec.storageClassName}'')\\" ]"]}, {"label": "StorageClass 가 fast-ssd 가 아니다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pvc data -n $NS -o jsonpath=''{.spec.storageClassName}'')\\" != fast-ssd ]"]}, {"label": "용량이 1Gi 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pvc data -n $NS -o jsonpath=''{.spec.resources.requests.storage}'')\\" = 1Gi ]"]}]', grade_cmd = '["sh", "-c", "( [ -n \\"$(kubectl get pvc data -n $NS -o jsonpath=''{.spec.storageClassName}'')\\" ] ) && ( [ \\"$(kubectl get pvc data -n $NS -o jsonpath=''{.spec.storageClassName}'')\\" != fast-ssd ] ) && ( [ \\"$(kubectl get pvc data -n $NS -o jsonpath=''{.spec.resources.requests.storage}'')\\" = 1Gi ] )"]' WHERE quest_set_id = 33 AND order_index = 5;
UPDATE quest SET checks = '[{"label": "Pod duo 의 컨테이너가 2개이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get pod duo -n $NS -o jsonpath=''{.spec.containers[*].name}'' | wc -w)\\" -eq 2 ]"]}, {"label": "nginx 이미지 컨테이너가 있다", "cmd": ["sh", "-c", "kubectl get pod duo -n $NS -o jsonpath=''{.spec.containers[*].image}'' | grep -q nginx"]}, {"label": "busybox 이미지 컨테이너가 있다", "cmd": ["sh", "-c", "kubectl get pod duo -n $NS -o jsonpath=''{.spec.containers[*].image}'' | grep -q busybox"]}, {"label": "두 컨테이너가 모두 준비(Ready)되었다", "cmd": ["sh", "-c", "kubectl wait --for=condition=Ready pod/duo -n $NS --timeout=10s"]}]', grade_cmd = '["sh", "-c", "( [ \\"$(kubectl get pod duo -n $NS -o jsonpath=''{.spec.containers[*].name}'' | wc -w)\\" -eq 2 ] ) && ( kubectl get pod duo -n $NS -o jsonpath=''{.spec.containers[*].image}'' | grep -q nginx ) && ( kubectl get pod duo -n $NS -o jsonpath=''{.spec.containers[*].image}'' | grep -q busybox ) && ( kubectl wait --for=condition=Ready pod/duo -n $NS --timeout=10s )"]' WHERE quest_set_id = 33 AND order_index = 7;
UPDATE quest SET checks = '[{"label": "ip_before.txt 와 ip_after.txt 에 IP 가 저장되어 있다", "cmd": ["sh", "-c", "[ -n \\"$(tr -d ''[:space:]'' < /tmp/ip_before.txt 2>/dev/null)\\" ] && [ -n \\"$(tr -d ''[:space:]'' < /tmp/ip_after.txt 2>/dev/null)\\" ]"]}, {"label": "두 IP 가 서로 다르다 (Pod 를 다시 만들면 IP 가 바뀐다)", "cmd": ["sh", "-c", "[ \\"$(tr -d ''[:space:]'' < /tmp/ip_before.txt 2>/dev/null)\\" != \\"$(tr -d ''[:space:]'' < /tmp/ip_after.txt 2>/dev/null)\\" ]"]}, {"label": "ip_after.txt 가 지금 실행 중인 web Pod 의 IP 이다", "cmd": ["sh", "-c", "p=$(kubectl get pods -n $NS -l app=web --no-headers | awk ''$3==\\"Running\\" {print $1}'' | head -n 1); [ \\"$(tr -d ''[:space:]'' < /tmp/ip_after.txt 2>/dev/null)\\" = \\"$(kubectl get pod $p -n $NS -o jsonpath=''{.status.podIP}'')\\" ]"]}]', grade_cmd = '["sh", "-c", "( [ -n \\"$(tr -d ''[:space:]'' < /tmp/ip_before.txt 2>/dev/null)\\" ] && [ -n \\"$(tr -d ''[:space:]'' < /tmp/ip_after.txt 2>/dev/null)\\" ] ) && ( [ \\"$(tr -d ''[:space:]'' < /tmp/ip_before.txt 2>/dev/null)\\" != \\"$(tr -d ''[:space:]'' < /tmp/ip_after.txt 2>/dev/null)\\" ] ) && ( p=$(kubectl get pods -n $NS -l app=web --no-headers | awk ''$3==\\"Running\\" {print $1}'' | head -n 1); [ \\"$(tr -d ''[:space:]'' < /tmp/ip_after.txt 2>/dev/null)\\" = \\"$(kubectl get pod $p -n $NS -o jsonpath=''{.status.podIP}'')\\" ] )"]' WHERE quest_set_id = 37 AND order_index = 2;

-- 세트 17(쉘 스크립트 기초) 전체를 조건별 채점으로: 실행 권한·#! 줄·동작 결과를 각각 체크리스트로 보여 준다 (grade_cmd 는 그대로, 같은 조건을 && 로 이은 것과 같다).
UPDATE quest SET checks = '[{"label": "스크립트에 실행 권한이 있다", "cmd": ["sh", "-c", "[ -x /tmp/hello.sh ]"]}, {"label": "첫 줄이 #! 로 시작한다 (어떤 쉘로 실행할지 적혀 있다)", "cmd": ["sh", "-c", "head -n 1 /tmp/hello.sh | grep -q ''^#!''"]}, {"label": "실행하면 hello etude 를 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/hello.sh)\\" = ''hello etude'' ]"]}]' WHERE quest_set_id = 17 AND order_index = 1;
UPDATE quest SET checks = '[{"label": "스크립트에 실행 권한이 있다", "cmd": ["sh", "-c", "[ -x /tmp/greet.sh ]"]}, {"label": "첫 줄이 #! 로 시작한다 (어떤 쉘로 실행할지 적혀 있다)", "cmd": ["sh", "-c", "head -n 1 /tmp/greet.sh | grep -q ''^#!''"]}, {"label": "Kim 을 넘기면 Hello, Kim 을 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/greet.sh Kim)\\" = ''Hello, Kim'' ]"]}, {"label": "Lee 를 넘기면 Hello, Lee 를 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/greet.sh Lee)\\" = ''Hello, Lee'' ]"]}]' WHERE quest_set_id = 17 AND order_index = 2;
UPDATE quest SET checks = '[{"label": "스크립트에 실행 권한이 있다", "cmd": ["sh", "-c", "[ -x /tmp/count_args.sh ]"]}, {"label": "첫 줄이 #! 로 시작한다 (어떤 쉘로 실행할지 적혀 있다)", "cmd": ["sh", "-c", "head -n 1 /tmp/count_args.sh | grep -q ''^#!''"]}, {"label": "인자 3개(a b c)를 넘기면 3 을 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/count_args.sh a b c)\\" = 3 ]"]}, {"label": "인자가 없으면 0 을 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/count_args.sh)\\" = 0 ]"]}]' WHERE quest_set_id = 17 AND order_index = 3;
UPDATE quest SET checks = '[{"label": "스크립트에 실행 권한이 있다", "cmd": ["sh", "-c", "[ -x /tmp/check_file.sh ]"]}, {"label": "첫 줄이 #! 로 시작한다 (어떤 쉘로 실행할지 적혀 있다)", "cmd": ["sh", "-c", "head -n 1 /tmp/check_file.sh | grep -q ''^#!''"]}, {"label": "있는 파일을 넘기면 exists 를 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/check_file.sh /etc/hostname)\\" = exists ]"]}, {"label": "없는 파일을 넘기면 missing 을 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/check_file.sh /nonexistent)\\" = missing ]"]}]' WHERE quest_set_id = 17 AND order_index = 4;
UPDATE quest SET checks = '[{"label": "스크립트에 실행 권한이 있다", "cmd": ["sh", "-c", "[ -x /tmp/is_big.sh ]"]}, {"label": "첫 줄이 #! 로 시작한다 (어떤 쉘로 실행할지 적혀 있다)", "cmd": ["sh", "-c", "head -n 1 /tmp/is_big.sh | grep -q ''^#!''"]}, {"label": "100 이면 big 을 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/is_big.sh 100)\\" = big ]"]}, {"label": "99 이면 small 을 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/is_big.sh 99)\\" = small ]"]}, {"label": "250 이면 big 을 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/is_big.sh 250)\\" = big ]"]}]' WHERE quest_set_id = 17 AND order_index = 5;
UPDATE quest SET checks = '[{"label": "스크립트에 실행 권한이 있다", "cmd": ["sh", "-c", "[ -x /tmp/seq_sum.sh ]"]}, {"label": "첫 줄이 #! 로 시작한다 (어떤 쉘로 실행할지 적혀 있다)", "cmd": ["sh", "-c", "head -n 1 /tmp/seq_sum.sh | grep -q ''^#!''"]}, {"label": "10 을 넘기면 55 를 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/seq_sum.sh 10)\\" = 55 ]"]}, {"label": "100 을 넘기면 5050 을 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/seq_sum.sh 100)\\" = 5050 ]"]}]' WHERE quest_set_id = 17 AND order_index = 6;
UPDATE quest SET checks = '[{"label": "스크립트에 실행 권한이 있다", "cmd": ["sh", "-c", "[ -x /tmp/count_logs.sh ]"]}, {"label": "첫 줄이 #! 로 시작한다 (어떤 쉘로 실행할지 적혀 있다)", "cmd": ["sh", "-c", "head -n 1 /tmp/count_logs.sh | grep -q ''^#!''"]}, {"label": ".log 파일이 3개 든 폴더에서는 3 을 출력한다", "cmd": ["sh", "-c", "d=$(mktemp -d); touch $d/a.log $d/b.log $d/c.log $d/x.txt; [ \\"$(/tmp/count_logs.sh $d)\\" = 3 ]"]}, {"label": ".log 파일이 없는 빈 폴더에서는 0 을 출력한다", "cmd": ["sh", "-c", "e=$(mktemp -d); [ \\"$(/tmp/count_logs.sh $e)\\" = 0 ]"]}]' WHERE quest_set_id = 17 AND order_index = 7;
UPDATE quest SET checks = '[{"label": "스크립트에 실행 권한이 있다", "cmd": ["sh", "-c", "[ -x /tmp/must_have.sh ]"]}, {"label": "첫 줄이 #! 로 시작한다 (어떤 쉘로 실행할지 적혀 있다)", "cmd": ["sh", "-c", "head -n 1 /tmp/must_have.sh | grep -q ''^#!''"]}, {"label": "status OK 가 든 파일이면 종료 코드 0 으로 끝난다", "cmd": ["sh", "-c", "echo ''status OK'' > /tmp/yes.txt; /tmp/must_have.sh /tmp/yes.txt; [ $? -eq 0 ]"]}, {"label": "status FAIL 이 든 파일이면 종료 코드 1 로 끝난다", "cmd": ["sh", "-c", "echo ''status FAIL'' > /tmp/no.txt; /tmp/must_have.sh /tmp/no.txt; [ $? -eq 1 ]"]}]' WHERE quest_set_id = 17 AND order_index = 8;
UPDATE quest SET checks = '[{"label": "스크립트에 실행 권한이 있다", "cmd": ["sh", "-c", "[ -x /tmp/alert.sh ]"]}, {"label": "첫 줄이 #! 로 시작한다 (어떤 쉘로 실행할지 적혀 있다)", "cmd": ["sh", "-c", "head -n 1 /tmp/alert.sh | grep -q ''^#!''"]}, {"label": "ERROR 가 4번 있는 로그에서 ERROR count: 4 를 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/alert.sh /tmp/svc.log)\\" = ''ERROR count: 4'' ]"]}, {"label": "ERROR 가 4번이면 종료 코드 1(경고)로 끝난다", "cmd": ["sh", "-c", "/tmp/alert.sh /tmp/svc.log >/dev/null; [ $? -eq 1 ]"]}, {"label": "ERROR 가 1번 있는 로그에서 ERROR count: 1 을 출력한다", "cmd": ["sh", "-c", "echo ERROR x > /tmp/svc2.log; [ \\"$(/tmp/alert.sh /tmp/svc2.log)\\" = ''ERROR count: 1'' ]"]}, {"label": "ERROR 가 1번이면 종료 코드 0(정상)으로 끝난다", "cmd": ["sh", "-c", "echo ERROR x > /tmp/svc2.log; /tmp/alert.sh /tmp/svc2.log >/dev/null; [ $? -eq 0 ]"]}]' WHERE quest_set_id = 17 AND order_index = 9;
UPDATE quest SET checks = '[{"label": "스크립트에 실행 권한이 있다", "cmd": ["sh", "-c", "[ -x /tmp/admins.sh ]"]}, {"label": "첫 줄이 #! 로 시작한다 (어떤 쉘로 실행할지 적혀 있다)", "cmd": ["sh", "-c", "head -n 1 /tmp/admins.sh | grep -q ''^#!''"]}, {"label": "members.csv 에서 관리자(kim, lee)만 한 줄씩 출력한다", "cmd": ["sh", "-c", "[ \\"$(/tmp/admins.sh /tmp/members.csv | paste -sd, -)\\" = kim,lee ]"]}]' WHERE quest_set_id = 17 AND order_index = 10;

-- 조건이 여러 개인 리눅스 문제를 조건별 채점으로 승격 (세트 15 #7·#12, 16 #3·#9, 21 #14, 27 #13, 35 #3). grade_cmd 는 그대로, 같은 조건을 && 로 이은 것과 같다.
UPDATE quest SET checks = '[{"label": "포트가 port=9090 으로 바뀌었다", "cmd": ["sh", "-c", "grep -qx ''port=9090'' /etc/app/app.conf"]}, {"label": "host=0.0.0.0 줄이 그대로 있다", "cmd": ["sh", "-c", "grep -qx ''host=0.0.0.0'' /etc/app/app.conf"]}, {"label": "timeout=30 줄이 그대로 있다", "cmd": ["sh", "-c", "grep -qx ''timeout=30'' /etc/app/app.conf"]}, {"label": "옛 포트 8080 이 어디에도 남아 있지 않다", "cmd": ["sh", "-c", "! grep -q 8080 /etc/app/app.conf"]}, {"label": "파일이 여전히 6줄이다 (다른 줄이 지워지지 않았다)", "cmd": ["sh", "-c", "[ \\"$(wc -l < /etc/app/app.conf)\\" -eq 6 ]"]}]' WHERE quest_set_id = 15 AND order_index = 12;
UPDATE quest SET checks = '[{"label": "최근 로그 recent.log 는 남아 있다", "cmd": ["sh", "-c", "[ -f /var/log/old-app/recent.log ]"]}, {"label": "30일 된 old1.log, old2.log 가 삭제됐다", "cmd": ["sh", "-c", "[ ! -e /var/log/old-app/old1.log ] && [ ! -e /var/log/old-app/old2.log ]"]}, {"label": "10일 된 old3.log 도 삭제됐다 (7일보다 오래된 파일)", "cmd": ["sh", "-c", "[ ! -e /var/log/old-app/old3.log ]"]}]' WHERE quest_set_id = 16 AND order_index = 3;
UPDATE quest SET checks = '[{"label": "deploy 사용자가 로그 폴더에 파일을 만들 수 있다", "cmd": ["sh", "-c", "su deploy -s /bin/sh -c ''touch /srv/app/logs/t.log''"]}, {"label": "아무나 쓸 수 있게(o+w) 열어 두지 않았다", "cmd": ["sh", "-c", "! find /srv/app/logs -maxdepth 0 -perm -o+w | grep -q ."]}]' WHERE quest_set_id = 16 AND order_index = 9;
UPDATE quest SET checks = '[{"label": "/etc/exports 에 /export/data 공유 줄이 있다", "cmd": ["sh", "-c", "grep -q ''^/export/data[[:space:]]'' /etc/exports"]}, {"label": "접속 허용 대역이 10.0.0.0/24 이다", "cmd": ["sh", "-c", "grep ''^/export/data[[:space:]]'' /etc/exports | grep -q ''10[.]0[.]0[.]0/24''"]}, {"label": "읽기·쓰기(rw) 옵션이 있다", "cmd": ["sh", "-c", "grep ''^/export/data[[:space:]]'' /etc/exports | grep -q ''rw''"]}, {"label": "sync 옵션이 있다", "cmd": ["sh", "-c", "grep ''^/export/data[[:space:]]'' /etc/exports | grep -q ''sync''"]}, {"label": "no_root_squash 옵션이 있다", "cmd": ["sh", "-c", "grep ''^/export/data[[:space:]]'' /etc/exports | grep -q ''no_root_squash''"]}]' WHERE quest_set_id = 27 AND order_index = 13;
UPDATE quest SET checks = '[{"label": "첫 줄이 기존 내용(first line) 그대로다", "cmd": ["sh", "-c", "[ \\"$(head -n 1 /tmp/notes.txt)\\" = ''first line'' ]"]}, {"label": "둘째 줄에 second line 이 추가됐다", "cmd": ["sh", "-c", "[ \\"$(sed -n 2p /tmp/notes.txt)\\" = ''second line'' ]"]}, {"label": "파일이 정확히 2줄이다 (덮어쓰거나 중복되지 않았다)", "cmd": ["sh", "-c", "[ \\"$(wc -l < /tmp/notes.txt)\\" -eq 2 ]"]}]' WHERE quest_set_id = 15 AND order_index = 7;
UPDATE quest SET checks = '[{"label": "두 파일이 같은 inode 를 가리킨다 (하드링크)", "cmd": ["sh", "-c", "[ \\"$(stat -c %i /tmp/orig.txt)\\" = \\"$(stat -c %i /tmp/hard.txt)\\" ]"]}, {"label": "링크 수가 2 이다", "cmd": ["sh", "-c", "[ \\"$(stat -c %h /tmp/orig.txt)\\" = 2 ]"]}, {"label": "심볼릭 링크가 아니라 하드링크다", "cmd": ["sh", "-c", "[ ! -L /tmp/hard.txt ]"]}]' WHERE quest_set_id = 21 AND order_index = 14;
UPDATE quest SET checks = '[{"label": "/tmp/seq 에 파일이 5개 만들어졌다", "cmd": ["sh", "-c", "[ \\"$(ls /tmp/seq | wc -l)\\" -eq 5 ]"]}, {"label": "file1.txt 가 있다", "cmd": ["sh", "-c", "[ -f /tmp/seq/file1.txt ]"]}, {"label": "file5.txt 가 있다", "cmd": ["sh", "-c", "[ -f /tmp/seq/file5.txt ]"]}]' WHERE quest_set_id = 35 AND order_index = 3;
